/* Apply CMS content to public Portfolio + Artikel */
(function(){
  const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const cfg=()=>window.RENTCAM_CMS_CONFIG||{};
  function nav(path){if(typeof go==='function')go(path);else location.href=path}
  function renderPortfolio(){const a=cfg().portfolio;if(!Array.isArray(a)||!a.length)return false;const app=document.getElementById('app');if(!app)return false;const p=location.pathname;if(p==='/portfolio'){const f=a[0],rest=a.slice(1);app.innerHTML=`<section class="rentcam-editorial"><div class="container"><div class="ed-hero"><div><div class="ed-kicker">Production Portfolio</div><h1>Stories built with cinema gear.</h1></div><p>Showcase produksi dengan camera package, cinema lens, lighting serta monitoring profesional.</p></div><article class="ed-feature" data-cms-go="/portfolio/${esc(f.id)}"><img src="${esc(f.img)}"><div class="ed-feature-copy"><div><small>${esc(f.year)} · ${esc(f.cat)} · Featured Project</small><h2>${esc(f.title)}</h2><p>${esc(f.desc)}</p></div><span class="ed-open">↗</span></div></article><div class="ed-grid">${rest.map(x=>`<article class="ed-card" data-cms-go="/portfolio/${esc(x.id)}"><img src="${esc(x.img)}" loading="lazy"><div class="ed-card-body"><small>${esc(x.year)} · ${esc(x.cat)}</small><h3>${esc(x.title)}</h3><p>${esc(x.desc)}</p><div class="ed-tags"><span class="ed-tag">${esc(x.camera||'')}</span><span class="ed-tag">${esc(x.lens||'')}</span></div></div></article>`).join('')}</div></div></section>`;return true}
    const m=p.match(/^\/portfolio\/([^/?#]+)/);if(m){const x=a.find(v=>String(v.id)===decodeURIComponent(m[1]))||a[0];app.innerHTML=`<section class="rentcam-editorial"><div class="container ed-detail"><button class="ed-back" data-cms-go="/portfolio">←</button><div class="ed-detail-meta">${esc(x.year)} · ${esc(x.cat)} · Rentcam Portfolio</div><h1>${esc(x.title)}</h1><p class="ed-lead">${esc(x.desc)}</p><img class="ed-detail-image" src="${esc(x.img)}"><div class="ed-copy"><div class="ed-copy-main"><p>${esc(x.body||'Project ini menggunakan konfigurasi equipment yang disesuaikan dengan kebutuhan visual, workflow set, dan mobilitas crew.')}</p></div><aside class="ed-side"><h3>Equipment</h3><div class="ed-side-row">Camera<b>${esc(x.camera||'-')}</b></div><div class="ed-side-row">Lenses<b>${esc(x.lens||'-')}</b></div><div class="ed-side-row">Production Type<b>${esc(x.cat||'-')}</b></div><div class="ed-side-row">Year<b>${esc(x.year||'-')}</b></div></aside></div></div></section>`;return true}return false}
  function renderArticles(){const a=cfg().articles;if(!Array.isArray(a)||!a.length)return false;const app=document.getElementById('app');if(!app)return false;const p=location.pathname;if(p==='/artikel'){const f=a[0],rest=a.slice(1);app.innerHTML=`<section class="rentcam-editorial"><div class="container"><div class="ed-hero"><div><div class="ed-kicker">Rentcam Journal</div><h1>Guides for better productions.</h1></div><p>Camera system, cinema lens, lighting, workflow set dan rental guide untuk produksi yang lebih siap.</p></div><article class="article-feature" data-cms-go="/artikel/${esc(f.id)}"><img src="${esc(f.img)}"><div class="article-feature-copy"><small>${esc(f.cat)} · ${esc(f.date)} · ${esc(f.read||'')}</small><h2>${esc(f.title)}</h2><p>${esc(f.excerpt)}</p><b>Baca artikel →</b></div></article><div class="ed-grid">${rest.map(x=>`<article class="ed-card" data-cms-go="/artikel/${esc(x.id)}"><img src="${esc(x.img)}" loading="lazy"><div class="ed-card-body"><small>${esc(x.cat)} · ${esc(x.date)} · ${esc(x.read||'')}</small><h3>${esc(x.title)}</h3><p>${esc(x.excerpt)}</p></div></article>`).join('')}</div></div></section>`;return true}
    const m=p.match(/^\/artikel\/([^/?#]+)/);if(m){const x=a.find(v=>String(v.id)===decodeURIComponent(m[1]))||a[0];const paragraphs=String(x.body||x.excerpt||'').split(/\n\n+/).filter(Boolean);app.innerHTML=`<section class="rentcam-editorial"><div class="container ed-detail"><button class="ed-back" data-cms-go="/artikel">←</button><div class="ed-detail-meta">${esc(x.cat)} · ${esc(x.date)} · ${esc(x.read||'')}</div><h1>${esc(x.title)}</h1><p class="ed-lead">${esc(x.excerpt)}</p><img class="ed-detail-image" src="${esc(x.img)}"><div class="ed-copy"><div class="ed-copy-main">${paragraphs.map(t=>`<p>${esc(t)}</p>`).join('')}</div><aside class="ed-side"><h3>Article Info</h3><div class="ed-side-row">Category<b>${esc(x.cat||'-')}</b></div><div class="ed-side-row">Published<b>${esc(x.date||'-')}</b></div><div class="ed-side-row">Reading Time<b>${esc(x.read||'-')}</b></div></aside></div></div></section>`;return true}return false}
  function run(){if(location.pathname.startsWith('/portfolio'))renderPortfolio();else if(location.pathname.startsWith('/artikel'))renderArticles()}
  document.addEventListener('rentcam-cms-updated',()=>requestAnimationFrame(run));document.addEventListener('click',e=>{const n=e.target.closest?.('[data-cms-go]');if(n){e.preventDefault();e.stopPropagation();nav(n.dataset.cmsGo);setTimeout(run,0)}},true);addEventListener('popstate',()=>setTimeout(run,0));setTimeout(run,500);
})();